output_text:
[
  {
    "id": "no_cart_in_one_wide_aisles",
    "text": "Shopping carts are prohibited in one-cell-wide aisles.",
    "abstraction": {
      "state_properties": {
        "one_wide_aisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "one_wide_aisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "no_cart_between_facing_shelves",
    "text": "Aisles with shelves immediately on both the east and west sides must be traversed without a cart.",
    "abstraction": {
      "state_properties": {
        "between_facing_shelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "between_facing_shelves",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "park_cart_on_arrival_at_narrow_mouth",
    "text": "When arriving with a cart at the mouth of a narrow shelf aisle, the cart must be parked there before proceeding.",
    "abstraction": {
      "state_properties": {
        "narrow_aisle_mouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "mouth_with_cart": {
          "and": [
            "narrow_aisle_mouth",
            "hasCart"
          ]
        }
      },
      "events": {
        "arrive_at_mouth_with_cart": {
          "pre": {
            "and": [
              "MOVE",
              {
                "not": "narrow_aisle_mouth"
              }
            ]
          },
          "post": "mouth_with_cart"
        },
        "drop_cart_at_mouth": {
          "pre": {
            "and": [
              "narrow_aisle_mouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "and": [
              "narrow_aisle_mouth",
              {
                "not": "hasCart"
              }
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "arrive_at_mouth_with_cart",
      "discharge": "drop_cart_at_mouth"
    }
  },
  {
    "id": "retrieve_cart_after_narrow_aisle",
    "text": "After entering a narrow shelf aisle without a cart, the shopper must return and retrieve the parked cart.",
    "abstraction": {
      "state_properties": {
        "narrow_aisle_mouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "one_wide_aisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "one_wide_without_cart": {
          "and": [
            "one_wide_aisle",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "enter_narrow_aisle_without_cart": {
          "pre": {
            "and": [
              "narrow_aisle_mouth",
              {
                "not": "hasCart"
              },
              "N"
            ]
          },
          "post": "one_wide_without_cart"
        },
        "pick_up_cart_at_mouth": {
          "pre": {
            "and": [
              "narrow_aisle_mouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": {
            "and": [
              "narrow_aisle_mouth",
              "hasCart"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enter_narrow_aisle_without_cart",
      "discharge": "pick_up_cart_at_mouth"
    }
  },
  {
    "id": "empty_hands_only_in_cart_free_zone",
    "text": "Inside the store, moving without a cart is forbidden except at the cart area, a narrow-aisle mouth, or inside a one-wide aisle.",
    "abstraction": {
      "state_properties": {
        "cart_area": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "narrow_aisle_mouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "one_wide_aisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "cart_free_zone": {
          "or": [
            "cart_area",
            "narrow_aisle_mouth",
            "one_wide_aisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "cart_free_zone"
          }
        ]
      }
    }
  },
  {
    "id": "drop_cart_only_at_narrow_mouths",
    "text": "Carts may only be set down at designated parking cells at the mouths of narrow shelf aisles.",
    "abstraction": {
      "state_properties": {
        "narrow_aisle_mouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "drop_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "drop_cart",
          {
            "not": "narrow_aisle_mouth"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_at_north_shelf_bays",
    "text": "Items on north-facing shelves along the broad lower aisle must be collected while keeping the cart.",
    "abstraction": {
      "state_properties": {
        "north_shelf_service_bay": {
          "and": [
            "adjShelf",
            "shelfN",
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "le": [
                "freeWidthV",
                2
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "north_shelf_service_bay",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "lower_shelf_bay_flow",
    "text": "After stopping at a lower north-facing shelf bay with a cart, shoppers must not move north or back west from that bay.",
    "abstraction": {
      "state_properties": {
        "lower_north_shelf_bay": {
          "and": [
            "adjShelf",
            "shelfN",
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "le": [
                "freeWidthV",
                2
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "lower_north_shelf_bay",
          "hasCart",
          {
            "or": [
              "N",
              "W"
            ]
          }
        ]
      }
    }
  }
]
